<template>
  <q-page class="admin-page">
    <main>
      <section class="welcome"><div><span>VISÃO GERAL</span><h1>Olá, {{ auth.user?.firstName || 'Administrador' }}</h1><p>Acompanhe utilizadores e salões da plataforma num só lugar.</p></div><q-btn outline rounded no-caps color="primary" icon="refresh" label="Actualizar dados" :loading="loading" @click="loadAll" /></section>

      <section class="metrics">
        <article><span class="metric-icon users"><q-icon name="group" /></span><div><small>Utilizadores</small><strong>{{ stats.users }}</strong><p>{{ stats.activeUsers }} activos</p></div></article>
        <article><span class="metric-icon salons"><q-icon name="storefront" /></span><div><small>Salões</small><strong>{{ stats.salons }}</strong><p>{{ stats.approvedSalons }} aprovados</p></div></article>
        <article><span class="metric-icon pending"><q-icon name="pending_actions" /></span><div><small>Aguardam análise</small><strong>{{ stats.pendingSalons }}</strong><p>salões pendentes</p></div></article>
        <article><span class="metric-icon blocked"><q-icon name="block" /></span><div><small>Contas bloqueadas</small><strong>{{ stats.blockedUsers }}</strong><p>requerem atenção</p></div></article>
      </section>

      <section class="workspace">
        <div class="workspace-tabs"><button type="button" :class="{active:tab==='salons'}" @click="tab='salons'"><q-icon name="storefront" /> Salões <span>{{ salons.length }}</span></button><button type="button" :class="{active:tab==='users'}" @click="tab='users'"><q-icon name="group" /> Utilizadores <span>{{ usersTotal }}</span></button></div>
        <div class="filters"><q-input v-model="search" outlined rounded dense debounce="350" :placeholder="tab==='salons'?'Pesquisar salão, NUIT ou localização':'Pesquisar nome ou email'" @update:model-value="handleSearch"><template #prepend><q-icon name="search" /></template><template #append><q-icon v-if="search" name="close" class="cursor-pointer" @click="search=''" /></template></q-input><q-select v-model="statusFilter" outlined rounded dense emit-value map-options :options="statusOptions" label="Estado" /></div>
        <q-banner v-if="error" rounded class="error-banner"><q-icon name="error_outline" /> {{ error }}<template #action><q-btn flat dense no-caps label="Tentar novamente" @click="loadAll" /></template></q-banner>

        <div v-if="loading && !hasData" class="skeleton-list"><q-skeleton v-for="item in 4" :key="item" height="82px" /></div>
        <template v-else-if="tab==='salons'">
          <div v-if="filteredSalons.length" class="data-list"><article v-for="salon in filteredSalons" :key="salon.id"><span class="entity-avatar salon-avatar"><q-icon name="storefront" /></span><div class="entity-main"><div class="entity-heading"><h2>{{ salon.name }}</h2><span class="status" :class="salon.status.toLowerCase()">{{ statusLabel(salon.status) }}</span></div><p><q-icon name="location_on" /> {{ salon.district }}, {{ salon.province }} <span>·</span> NUIT {{ salon.nuit }}</p><small>Proprietário: {{ salon.owner.firstName }} {{ salon.owner.lastName }} · {{ salon.owner.email }}</small></div><div class="row-actions"><q-btn v-if="salon.status!=='APPROVED'" unelevated rounded no-caps color="positive" icon="check" label="Aprovar" @click="askStatus('salon',salon,'APPROVED')" /><q-btn-dropdown flat round dropdown-icon="more_vert"><q-list dense><q-item v-if="salon.status!=='BLOCKED'" clickable v-close-popup @click="askStatus('salon',salon,'BLOCKED')"><q-item-section avatar><q-icon name="block" color="negative" /></q-item-section><q-item-section>Bloquear salão</q-item-section></q-item><q-item v-if="salon.status!=='INACTIVE'" clickable v-close-popup @click="askStatus('salon',salon,'INACTIVE')"><q-item-section avatar><q-icon name="pause_circle" /></q-item-section><q-item-section>Desactivar</q-item-section></q-item><q-separator /><q-item clickable v-close-popup @click="askRemoveSalon(salon)"><q-item-section avatar><q-icon name="delete_outline" color="negative" /></q-item-section><q-item-section>Remover salão</q-item-section></q-item></q-list></q-btn-dropdown></div></article></div>
          <div v-else class="empty-state"><span><q-icon name="storefront" /></span><h2>Nenhum salão encontrado</h2><p>{{ search || statusFilter ? 'Altere os filtros para ver outros resultados.' : 'Os novos salões aparecerão aqui para aprovação.' }}</p></div>
        </template>
        <template v-else>
          <div v-if="users.length" class="data-list"><article v-for="user in users" :key="user.id"><q-avatar color="pink-1" text-color="primary">{{ user.firstName[0] }}{{ user.lastName[0] }}</q-avatar><div class="entity-main"><div class="entity-heading"><h2>{{ user.firstName }} {{ user.lastName }}</h2><span class="status" :class="user.status.toLowerCase()">{{ statusLabel(user.status) }}</span></div><p><q-icon name="mail_outline" /> {{ user.email }}</p><div class="roles"><span v-for="role in user.roles" :key="role">{{ roleLabel(role) }}</span></div></div><div class="row-actions"><q-btn v-if="user.status!=='ACTIVE'" unelevated rounded no-caps color="positive" icon="check" label="Activar" @click="askStatus('user',user,'ACTIVE')" /><q-btn-dropdown flat round dropdown-icon="more_vert"><q-list dense><q-item v-if="user.status!=='BLOCKED'" clickable v-close-popup @click="askStatus('user',user,'BLOCKED')"><q-item-section avatar><q-icon name="block" color="negative" /></q-item-section><q-item-section>Bloquear utilizador</q-item-section></q-item><q-separator /><q-item clickable v-close-popup @click="askRemoveUser(user)"><q-item-section avatar><q-icon name="delete_outline" color="negative" /></q-item-section><q-item-section>Remover utilizador</q-item-section></q-item></q-list></q-btn-dropdown></div></article></div>
          <div v-else class="empty-state"><span><q-icon name="person_search" /></span><h2>Nenhum utilizador encontrado</h2><p>Altere a pesquisa ou o filtro seleccionado.</p></div>
        </template>
      </section>
    </main>

    <q-dialog v-model="confirmDialog"><q-card class="confirm-card"><q-card-section><span class="confirm-icon" :class="isDangerAction?'danger':'safe'"><q-icon :name="pendingAction.type==='removeSalon'||pendingAction.type==='removeUser'?'delete_outline':pendingAction.status==='BLOCKED'?'block':'check_circle'" /></span><h2>{{ confirmTitle }}</h2><p>{{ confirmMessage }}</p></q-card-section><q-card-actions align="right"><q-btn v-close-popup flat rounded no-caps label="Cancelar" /><q-btn unelevated rounded no-caps :color="isDangerAction?'negative':'primary'" label="Confirmar" :loading="actionLoading" @click="applyStatus" /></q-card-actions></q-card></q-dialog>
  </q-page>
</template>

<script setup>
import { computed,onMounted,reactive,ref,watch } from 'vue';import { gql } from '@apollo/client/core';import { apolloClient } from 'boot/apollo';import { useAuthStore } from 'stores/auth-store'
const auth=useAuthStore(),tab=ref('salons'),search=ref(''),statusFilter=ref(null),loading=ref(true),actionLoading=ref(false),error=ref(''),salons=ref([]),users=ref([]),usersTotal=ref(0),stats=reactive({users:0,activeUsers:0,blockedUsers:0,salons:0,approvedSalons:0,pendingSalons:0}),confirmDialog=ref(false),pendingAction=reactive({type:'',entity:null,status:''})
const ADMIN_SALONS=gql`query AdminOverview{adminSalons{id name nuit district province status owner{email firstName lastName}} adminStats{users activeUsers blockedUsers salons approvedSalons pendingSalons}}`;const USERS=gql`query Users($filter:UsersFilter){users(filter:$filter){items{id email firstName lastName status roles}total}}`;const SALON_STATUS=gql`mutation SalonStatus($id:ID!,$status:SalonStatus!){updateSalonStatus(salonId:$id,status:$status){id status}}`;const USER_STATUS=gql`mutation UserStatus($id:ID!,$status:UserStatus!){updateUserStatus(userId:$id,status:$status){id status}}`;const REMOVE_SALON=gql`mutation RemoveSalon($id:ID!){removeSalon(salonId:$id)}`;const REMOVE_USER=gql`mutation RemoveUser($id:ID!){removeUser(userId:$id)}`
const hasData=computed(()=>salons.value.length||users.value.length)
const statusOptions=computed(()=>[{label:'Todos os estados',value:null},...(tab.value==='salons'?[{label:'Pendente',value:'PENDING'},{label:'Aprovado',value:'APPROVED'},{label:'Bloqueado',value:'BLOCKED'},{label:'Inactivo',value:'INACTIVE'}]:[{label:'Activo',value:'ACTIVE'},{label:'Pendente',value:'PENDING'},{label:'Bloqueado',value:'BLOCKED'},{label:'Inactivo',value:'INACTIVE'}])]);const filteredSalons=computed(()=>{const term=search.value.trim().toLowerCase();return salons.value.filter(s=>(!statusFilter.value||s.status===statusFilter.value)&&(!term||`${s.name} ${s.nuit} ${s.district} ${s.province} ${s.owner.email}`.toLowerCase().includes(term)))})
async function loadAll(){loading.value=true;error.value='';try{const [salonResult,userResult]=await Promise.all([apolloClient.query({query:ADMIN_SALONS,fetchPolicy:'network-only'}),apolloClient.query({query:USERS,variables:{filter:{pageSize:100,search:tab.value==='users'&&search.value?search.value:undefined,status:tab.value==='users'&&statusFilter.value?statusFilter.value:undefined}},fetchPolicy:'network-only'})]);salons.value=salonResult.data.adminSalons;Object.assign(stats,salonResult.data.adminStats);users.value=userResult.data.users.items;usersTotal.value=userResult.data.users.total}catch(e){error.value=e.message}finally{loading.value=false}}
function handleSearch(){if(tab.value==='users')loadUsers()}async function loadUsers(){loading.value=true;try{const {data}=await apolloClient.query({query:USERS,variables:{filter:{pageSize:100,search:search.value||undefined,status:statusFilter.value||undefined}},fetchPolicy:'network-only'});users.value=data.users.items;usersTotal.value=data.users.total}catch(e){error.value=e.message}finally{loading.value=false}}
function askStatus(type,entity,status){pendingAction.type=type;pendingAction.entity=entity;pendingAction.status=status;confirmDialog.value=true}
function askRemoveSalon(entity){pendingAction.type='removeSalon';pendingAction.entity=entity;pendingAction.status='';confirmDialog.value=true}
function askRemoveUser(entity){pendingAction.type='removeUser';pendingAction.entity=entity;pendingAction.status='';confirmDialog.value=true}
const isDangerAction=computed(()=>pendingAction.type==='removeSalon'||pendingAction.type==='removeUser'||pendingAction.status==='BLOCKED')
const entityName=computed(()=>pendingAction.entity?.name||`${pendingAction.entity?.firstName||''} ${pendingAction.entity?.lastName||''}`.trim())
const confirmTitle=computed(()=>pendingAction.type==='removeSalon'?'Remover salão?':pendingAction.type==='removeUser'?'Remover utilizador?':pendingAction.status==='BLOCKED'?'Confirmar bloqueio':pendingAction.status==='APPROVED'?'Aprovar salão?':pendingAction.status==='ACTIVE'?'Activar utilizador?':'Confirmar alteração')
const confirmMessage=computed(()=>pendingAction.type==='removeSalon'?`“${entityName.value}” deixará de aparecer na plataforma. O histórico de marcações é mantido, mas esta acção não pode ser desfeita por aqui.`:pendingAction.type==='removeUser'?`“${entityName.value}” deixará de poder aceder à plataforma. O histórico é mantido, mas esta acção não pode ser desfeita por aqui.`:`O estado de “${entityName.value}” será alterado para ${statusLabel(pendingAction.status).toLowerCase()}.`)
async function applyStatus(){actionLoading.value=true;try{if(pendingAction.type==='removeSalon')await apolloClient.mutate({mutation:REMOVE_SALON,variables:{id:pendingAction.entity.id}});else if(pendingAction.type==='removeUser')await apolloClient.mutate({mutation:REMOVE_USER,variables:{id:pendingAction.entity.id}});else if(pendingAction.type==='salon')await apolloClient.mutate({mutation:SALON_STATUS,variables:{id:pendingAction.entity.id,status:pendingAction.status}});else await apolloClient.mutate({mutation:USER_STATUS,variables:{id:pendingAction.entity.id,status:pendingAction.status}});confirmDialog.value=false;await loadAll()}catch(e){error.value=e.message}finally{actionLoading.value=false}}
const statusLabel=status=>({PENDING:'Pendente',APPROVED:'Aprovado',BLOCKED:'Bloqueado',INACTIVE:'Inactivo',ACTIVE:'Activo'}[status]??status);const roleLabel=role=>({ADMIN:'Administrador',SALON_OWNER:'Proprietário',SPECIALIST:'Especialista',CUSTOMER:'Cliente'}[role]??role);watch(tab,()=>{search.value='';statusFilter.value=null;if(tab.value==='users')loadUsers()});watch(statusFilter,()=>{if(tab.value==='users')loadUsers()});onMounted(loadAll)
</script>

<style scoped lang="scss">
.admin-page{min-height:100vh;background:#f8f5f6;color:#30262a}main{width:min(calc(100% - 40px),1180px);margin:auto;padding:35px 0 105px}.welcome{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:25px}.welcome>div>span{color:#ac124d;font-size:10px;font-weight:800;letter-spacing:1.4px}.welcome h1{margin:3px 0;font-size:30px}.welcome p{margin:0;color:#887d80;font-size:13px}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:13px;margin-bottom:22px}.metrics article{display:flex;align-items:center;gap:13px;padding:18px;border:1px solid #eee4e7;border-radius:18px;background:#fff;box-shadow:0 7px 22px rgba(70,28,43,.04)}.metric-icon{display:grid;width:45px;height:45px;flex:none;place-items:center;border-radius:14px;font-size:22px}.metric-icon.users{background:#e8edff;color:#5268c9}.metric-icon.salons{background:#fbe4ec;color:#ac124d}.metric-icon.pending{background:#fff1d6;color:#a67208}.metric-icon.blocked{background:#fde8e9;color:#b72b39}.metrics article>div{display:flex;flex-direction:column}.metrics small{color:#877b7f;font-size:10px}.metrics strong{font-size:23px;line-height:1.2}.metrics p{margin:0;color:#a09598;font-size:9px}.workspace{overflow:hidden;border:1px solid #eee4e7;border-radius:21px;background:#fff;box-shadow:0 10px 32px rgba(69,26,42,.05)}.workspace-tabs{display:flex;padding:8px 14px 0;border-bottom:1px solid #eee8ea}.workspace-tabs button{display:flex;align-items:center;gap:7px;padding:13px 16px;border:0;border-bottom:2px solid transparent;background:none;color:#8b7f83;font-weight:700}.workspace-tabs button.active{border-color:#b31250;color:#a9114c}.workspace-tabs button span{padding:2px 7px;border-radius:8px;background:#f3edef;font-size:9px}.filters{display:grid;grid-template-columns:minmax(220px,1fr) 190px;gap:9px;padding:17px;border-bottom:1px solid #f1eaec}.error-banner{margin:14px;background:#feecee;color:#aa2130}.data-list{display:grid}.data-list article{display:flex;min-height:91px;align-items:center;gap:14px;padding:15px 18px;border-bottom:1px solid #f1eaec}.data-list article:last-child{border-bottom:0}.data-list article:hover{background:#fdfafb}.entity-avatar{display:grid;width:46px;height:46px;flex:none;place-items:center;border-radius:14px;font-size:22px}.salon-avatar{background:#f9e6ed;color:#ac124d}.entity-main{min-width:0;flex:1}.entity-heading{display:flex;align-items:center;gap:8px}.entity-heading h2{margin:0;font-size:14px}.entity-main p{margin:5px 0 3px;color:#766b6f;font-size:11px}.entity-main small{color:#9a8e92;font-size:10px}.roles{display:flex;gap:5px;margin-top:5px}.roles span{padding:3px 7px;border-radius:7px;background:#f1ebed;color:#6e6266;font-size:8px;font-weight:700}.status{padding:4px 8px;border-radius:8px;background:#fff1d4;color:#8b6204;font-size:8px;font-weight:800;text-transform:uppercase}.status.approved,.status.active{background:#def6e9;color:#177047}.status.blocked{background:#fee6e8;color:#ad2332}.status.inactive{background:#eee;color:#686064}.row-actions{display:flex;align-items:center;gap:5px}.row-actions .q-btn{font-size:10px}.empty-state{padding:65px 20px;text-align:center}.empty-state>span{display:grid;width:68px;height:68px;margin:auto;place-items:center;border-radius:22px;background:#f7ecef;color:#c17792;font-size:32px}.empty-state h2{margin:14px 0 5px;font-size:18px}.empty-state p{margin:0;color:#92868a;font-size:11px}.skeleton-list{display:grid;gap:2px;padding:10px}.confirm-card{width:min(90vw,400px);padding:16px;border-radius:22px;text-align:center}.confirm-icon{display:grid;width:58px;height:58px;margin:0 auto 12px;place-items:center;border-radius:19px;font-size:30px}.confirm-icon.safe{background:#e0f7ec;color:#19744a}.confirm-icon.danger{background:#fee8e9;color:#b52736}.confirm-card h2{margin:0 0 7px;font-size:20px;line-height:1.25}.confirm-card p{margin:0;color:#83777b;font-size:12px}@media(max-width:850px){.metrics{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){main{width:calc(100% - 24px);padding-top:22px}.welcome{align-items:flex-start;flex-direction:column;gap:16px}.welcome .q-btn{height:42px;padding:0 18px}.metrics{gap:8px}.metrics article{padding:12px}.metric-icon{width:38px;height:38px}.filters{grid-template-columns:1fr}.data-list article{align-items:flex-start}.row-actions{align-items:flex-end;flex-direction:column}.entity-main small{display:none}.workspace-tabs button{flex:1;justify-content:center;padding:12px 5px}}</style>
